import{_ as r,o,a as t,ag as a}from"./chunks/framework.Do1Zayaf.js";const p=JSON.parse('{"title":"Worker-to-Server Communication & Result Aggregation","description":"","frontmatter":{},"headers":[],"relativePath":"aidoc/roxie-kb/worker-to-server.md","filePath":"aidoc/roxie-kb/worker-to-server.md","lastUpdated":1779520499000}'),i={name:"aidoc/roxie-kb/worker-to-server.md"};function s(n,e,c,d,l,u){return o(),t("div",null,e[0]||(e[0]=[a('<h1 id="worker-to-server-communication-result-aggregation" tabindex="-1">Worker-to-Server Communication &amp; Result Aggregation <a class="header-anchor" href="#worker-to-server-communication-result-aggregation" aria-label="Permalink to &quot;Worker-to-Server Communication &amp; Result Aggregation&quot;">​</a></h1><p>This document details the data path of execution results returning from Worker (Agent) nodes back to the orchestrating Roxie Server.</p><h2 id="worker-side-data-transmit" tabindex="-1">Worker-Side Data Transmit <a class="header-anchor" href="#worker-side-data-transmit" aria-label="Permalink to &quot;Worker-Side Data Transmit&quot;">​</a></h2><p>When an activity executes on a worker node (e.g., <code>CRoxieKeyedJoinIndexActivity</code> in <code>roxie/ccd/ccdactivities.cpp</code>), it processes the subset graph (reads index structures) and serializes the result rows.</p><ol><li>The activity calls <code>ROQ-&gt;createOutputStream(...)</code> to obtain an <code>IMessagePacker</code>.</li><li>As rows are returned (or matches found), they are natively allocated via <code>roxiemem</code> and processed.</li><li>They are handed over to the <code>IMessagePacker</code> (sometimes via helpers like <code>OptimizedKJRowBuilder</code>).</li><li>If a row exceeds optimal MTU limits or <code>roxiemem::DATA_ALIGNMENT_SIZE</code>, the packer fragments it into a multi-part payload.</li><li>The packet sequences are dispatched out natively using <code>ISendManager</code> (and the UDP/TCP send managers handle backpressure to the OS).</li></ol><h2 id="server-side-reception-cremoteresultadaptor" tabindex="-1">Server-Side Reception (<code>CRemoteResultAdaptor</code>) <a class="header-anchor" href="#server-side-reception-cremoteresultadaptor" aria-label="Permalink to &quot;Server-Side Reception (`CRemoteResultAdaptor`)&quot;">​</a></h2><p>When a Server orchestrates a distributed query via <code>CRoxieServerRemoteActivity</code> or <code>CRoxieServerKeyedJoinActivity</code> (in <code>roxie/ccd/ccdactivities.cpp</code>), it waits for the split data streams via the <code>CRemoteResultAdaptor</code> (defined in <code>roxie/ccd/ccdserver.cpp</code>). <code>CRemoteResultAdaptor</code> intercepts UDP/TCP messages and merges them back into a cohesive dataset using <code>CRemoteResultMerger</code>.</p><h3 id="the-result-merger-cremoteresultmerger" tabindex="-1">The Result Merger (<code>CRemoteResultMerger</code>) <a class="header-anchor" href="#the-result-merger-cremoteresultmerger" aria-label="Permalink to &quot;The Result Merger (`CRemoteResultMerger`)&quot;">​</a></h3><p><code>CRemoteResultMerger</code> is responsible for aggregating partial asynchronous remote results from multiple workers.</p><ul><li>It maintains a list of <code>HeapEntry</code> structs mapping sequence packets to memory block chunks.</li><li>It implements a local min-heap (<code>makeHeap()</code> and <code>remakeHeap()</code>) based on index comparisons to yield sequential rows in strictly sorted order.</li><li><code>nextRowGE()</code> and <code>skipRows()</code> handle Smart-Stepping skipping over unneeded sequence boundaries without full deserialization.</li></ul><h2 id="bottleneck-points-and-contention-worker-to-server" tabindex="-1">Bottleneck Points and Contention (Worker-to-Server) <a class="header-anchor" href="#bottleneck-points-and-contention-worker-to-server" aria-label="Permalink to &quot;Bottleneck Points and Contention (Worker-to-Server)&quot;">​</a></h2><ol><li><p><strong>Agent Message Packing Overhead</strong>: Every result row generated on the Worker forces memory packing calls before transmission (<code>output-&gt;getBuffer()</code>, <code>memcpy()</code>). High-throughput result generation inherently bottlenecked by memory-copy mechanics to fragment the data.</p></li><li><p><strong>Server-Side Result Aggregation (Heap Sorting)</strong>: The <code>CRemoteResultMerger</code> uses <code>makeHeap()</code> which demands CPU overhead on the central Server. Rebuilding or sliding tree heaps dynamically on varying UDP arrival sequences scales poorly with high Worker-fanout counts. In scenarios like massive Keyed Joins, yielding sequential <code>next()</code> rows from many workers simultaneously requires recurrent heap property restorations, eating memory bandwidth and CPU cycles.</p></li><li><p><strong>Limits Checking &amp; Concurrency Locks</strong>: In <code>CRemoteResultAdaptor::processRow()</code>, rows are individually evaluated against global <code>rowLimit</code> and <code>keyedLimit</code>. Furthermore, <code>ChannelBuffer</code> allocations use strict mutual exclusion (<code>CriticalSection crit</code>). Consequently, reading merged data is fiercely synchronized, capping single-thread retrieval speeds even when the network buffer has ample bytes.</p></li><li><p><strong>Incast Flooding</strong>: During Worker-to-Server consolidation, if many leaf nodes match on a distributed key simultaneously, they all blast UDP/TCP messages back to the originating server. While RTS/CTS partially throttles UDP, large synchronized queries can cause temporary packet queues to spike, exacerbating jitter for concurrent queries.</p></li></ol>',12)]))}const h=r(i,[["render",s]]);export{p as __pageData,h as default};
